{"content": "{
  "main_characters": [
    {
      "name": "沈凌",
      "role": "protagonist",
      "identity": "刑警队长，绑定犯罪预警系统",
      "traits": ["理性", "冷峻", "深情", "挣扎", "孤独"],
      "overt_motivation": "破解未婚妻要杀他的未来命案，阻止悲剧发生",
      "covert_motivation": "即使牺牲自己也要拯救她，不惜对抗命运",
      "secret_fear": "亲眼看着她走向毁灭，自己却无能为力",
      "misperception_of_other": "以为她真的想杀他，不知道她的真实动机是为理想牺牲",
      "hidden_connection": "三年前是她父亲的学生，曾受她父亲救命之恩"
    },
    {
      "name": "苏晚",
      "role": "deuteragonist",
      "identity": "法医，沈凌的未婚妻",
      "traits": ["冷静", "专业", "复杂", "深情", "决绝"],
      "overt_motivation": "维持表面平静，不让计划被发现，适时执行任务",
      "covert_motivation": "为阻止他接触那个会导致更大灾难的证人，她必须杀他",
      "secret_fear": "她的计划被发现/她真的爱上他无法下手",
      "misperception_of_other": "以为他只是个工作狂警察，不知道他拥有能看到凶手倒计时的系统",
      "hidden_connection": "是三年前那场案子的关键人物，她父亲死于那场案件"
    }
  ],
  "supporting_characters": [
    {
      "name": "程澈",
      "function": "反转点",
      "identity": "神秘的污点证人",
      "description": "掌握会导致更大灾难的秘密，被多方追逐"
    },
    {
      "name": "陆征",
      "function": "助力",
      "identity": "沈凌的刑警同事",
      "description": "忠诚的搭档，调查过程中的重要助力"
    },
    {
      "name": "林小满",
      "function": "阻碍",
      "identity": "苏晚的法医助手",
      "description": "无意中提供线索给沈凌，间接阻碍苏晚的计划"
    },
    {
      "name": "陈建国",
      "function": "反转点",
      "identity": "刑警局局长",
      "description": "施加时间压力的上级，背后有隐藏身份"
    }
  ],
  "relationship_dynamics": "沈凌与苏晚是未婚夫妻，却陷入'凶手与受害者'的极致对立。沈凌拥有系统能看到苏晚要杀他的倒计时，却必须假装不知道暗中调查；苏晚不知道沈凌已经发现她的计划，在倒计时中等待执行任务。12小时的倒计时如同达摩克利斯之剑，让每一秒都充满张力。"
}
